cells = [
{"cell_type":"markdown","metadata":{},"source":["# Population Column Data Quality QC (memory-safe)\n","\n","This notebook evaluates raw `profiles_before_clean` files across the cohort. It processes one CSV at a time and does not interpolate, clean, delete, or cache all profiles in memory."]},
{"cell_type":"code","execution_count":None,"metadata":{},"outputs":[],"source":["from pathlib import Path\nimport re\nimport gc\nimport numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\n\nRESULTS_ROOT = Path('/mnt/newStor/paros/paros_WORK/xintong/results/column_analysis')\nPROFILE_ROOT = RESULTS_ROOT\nQC_ROOT = Path('/mnt/newStor/paros/paros_WORK/xintong/results/column_quality_qc')\nQC_ROOT.mkdir(parents=True, exist_ok=True)\nPATTERN = re.compile(r'^(?P<subject>D\\d+)_(?P<hemi>lh|rh)_(?P<region>.+)_(?P<metric>md|fa|ad|rd)\\.csv$')\nprint('Output:', QC_ROOT)"]},
{"cell_type":"markdown","metadata":{},"source":["## 1. File-level inventory and bad-point summary\n\nOnly one profile file is loaded at a time. Empty files are recorded explicitly and are not interpreted as valid zero profiles."]},
{"cell_type":"code","execution_count":None,"metadata":{},"outputs":[],"source":["rows = []\nfor profile_dir in sorted(PROFILE_ROOT.glob('D*/profiles_before_clean')):\n    for path in sorted(profile_dir.glob('*.csv')):\n        m = PATTERN.match(path.name)\n        if not m: continue\n        meta = m.groupdict()\n        base = {**meta, 'path': str(path), 'file_size_bytes': path.stat().st_size}\n        if path.stat().st_size == 0:\n            rows.append({**base, 'status':'empty', 'n_columns':0, 'n_samples':0, 'bad_points':0, 'zero_points':0, 'nan_points':0, 'inf_points':0, 'consecutive_columns':0})\n            continue\n        try:\n            a = np.loadtxt(path, delimiter=',', ndmin=2)\n            bad = (~np.isfinite(a)) | (a == 0)\n            padded = np.pad(bad, ((0,0),(1,1)), constant_values=False)\n            runs = np.diff(padded.astype(np.int8), axis=1)\n            max_run = np.max(np.maximum(0, np.diff(np.where(runs != 0)[1].reshape(-1,2), axis=1))) if np.any(runs) else 0\n            consecutive = int(np.sum(np.max(bad[:,1:] & bad[:,:-1], axis=1))) if a.shape[1] > 1 else 0\n            rows.append({**base, 'status':'valid', 'n_columns':a.shape[0], 'n_samples':a.size, 'bad_points':int(bad.sum()), 'zero_points':int((a==0).sum()), 'nan_points':int(np.isnan(a).sum()), 'inf_points':int(np.isinf(a).sum()), 'consecutive_columns':consecutive})\n            del a, bad, padded, runs\n            gc.collect()\n        except Exception as exc:\n            rows.append({**base, 'status':'unreadable', 'n_columns':0, 'n_samples':0, 'bad_points':0, 'zero_points':0, 'nan_points':0, 'inf_points':0, 'consecutive_columns':0, 'error':str(exc)})\nfiles = pd.DataFrame(rows)\nfiles.to_csv(QC_ROOT/'profile_file_inventory.csv', index=False)\nprint('Files:',len(files),'Subjects:',files.subject.nunique())\ndisplay(files.head())"]},
{"cell_type":"markdown","metadata":{},"source":["## 2. Subject, metric, hemisphere and region summaries"]},
{"cell_type":"code","execution_count":None,"metadata":{},"outputs":[],"source":["def summarize(group):\n    out = group.agg(total_profiles=('path','size'), empty_profiles=('status',lambda s:int((s=='empty').sum())), unreadable_profiles=('status',lambda s:int((s=='unreadable').sum())), total_columns=('n_columns','sum'), total_samples=('n_samples','sum'), bad_points=('bad_points','sum'), zero_points=('zero_points','sum'), nan_points=('nan_points','sum'), inf_points=('inf_points','sum'), columns_with_consecutive_bad_points=('consecutive_columns','sum')).reset_index()\n    out['bad_point_pct'] = 100*out.bad_points/out.total_samples.replace(0,np.nan)\n    return out\nsubject_summary=summarize(files.groupby('subject'))\nmetric_summary=summarize(files.groupby('metric'))\nregion_summary=summarize(files.groupby(['subject','hemi','region','metric']))\nsubject_summary.to_csv(QC_ROOT/'subject_badpoint_summary.csv',index=False)\nmetric_summary.to_csv(QC_ROOT/'metric_badpoint_summary.csv',index=False)\nregion_summary.to_csv(QC_ROOT/'subject_hemisphere_region_metric_summary.csv',index=False)\ndisplay(subject_summary); display(metric_summary)"]},
{"cell_type":"markdown","metadata":{},"source":["## 3. Bad points per column and depth distribution\n\nThis cell again reads one file at a time and writes compact summaries instead of retaining all column vectors."]},
{"cell_type":"code","execution_count":None,"metadata":{},"outputs":[],"source":["category_rows=[]; depth_rows=[]\nfor _, row in files[files.status=='valid'].iterrows():\n    a=np.loadtxt(row.path,delimiter=',',ndmin=2)\n    bad=(~np.isfinite(a))|(a==0)\n    counts=bad.sum(axis=1)\n    category_rows += [{'subject':row.subject,'hemi':row.hemi,'region':row.region,'metric':row.metric,'category':('1' if n==1 else '2' if n==2 else '3_or_more' if n>=3 else '0'),'column_count':1} for n in counts]\n    depth_rows += [{'subject':row.subject,'hemi':row.hemi,'region':row.region,'metric':row.metric,'depth':int(d),'bad_point_count':int(n)} for d,n in enumerate(bad.sum(axis=0)) if n]\n    del a,bad,counts\n    gc.collect()\ncolumn_categories=pd.DataFrame(category_rows).groupby(['subject','hemi','region','metric','category'],as_index=False).column_count.sum()\ndepth_detail=pd.DataFrame(depth_rows)\ncolumn_categories.to_csv(QC_ROOT/'bad_points_per_column_summary.csv',index=False)\ndepth_detail.to_csv(QC_ROOT/'depth_bad_point_detail.csv',index=False)\ndisplay(column_categories.head(20)); display(depth_detail.head())"]},
{"cell_type":"markdown","metadata":{},"source":["## 4. Cross-metric overlap\n\nMatching metric files are loaded only for one subject × hemisphere × region at a time."]},
{"cell_type":"code","execution_count":None,"metadata":{},"outputs":[],"source":["overlap_rows=[]\nfor key, group in files[files.status=='valid'].groupby(['subject','hemi','region']):\n    paths={r.metric:r.path for _,r in group.iterrows()}\n    if set(paths)!=set(('md','fa','ad','rd')): continue\n    arrays=[]\n    try:\n        for metric in ('md','fa','ad','rd'):\n            a=np.loadtxt(paths[metric],delimiter=',',ndmin=2)\n            arrays.append((~np.isfinite(a))|(a==0))\n        shape={x.shape for x in arrays}\n        if len(shape)==1:\n            stack=np.stack(arrays)\n            overlap_rows.append({'subject':key[0],'hemi':key[1],'region':key[2],'total_coordinates':int(stack.shape[1]*stack.shape[2]),'bad_in_any_metric':int(np.any(stack,axis=0).sum()),'bad_in_all_metrics':int(np.all(stack,axis=0).sum())})\n    finally:\n        del arrays\n        gc.collect()\noverlap=pd.DataFrame(overlap_rows)\nif not overlap.empty:\n    overlap['any_metric_bad_pct']=100*overlap.bad_in_any_metric/overlap.total_coordinates\n    overlap['all_metric_overlap_pct']=100*overlap.bad_in_all_metrics/overlap.total_coordinates\noverlap.to_csv(QC_ROOT/'cross_metric_overlap_summary.csv',index=False)\ndisplay(overlap.head())"]},
{"cell_type":"markdown","metadata":{},"source":["## 5. Population visualizations"]},
{"cell_type":"code","execution_count":None,"metadata":{},"outputs":[],"source":["fig,axes=plt.subplots(1,3,figsize=(18,5))\nplot=subject_summary.sort_values('subject')\naxes[0].bar(plot.subject,plot.bad_point_pct); axes[0].set_title('Bad-point percentage by subject'); axes[0].tick_params(axis='x',rotation=90); axes[0].set_ylabel('%')\naxes[1].bar(metric_summary.metric.str.upper(),metric_summary.bad_point_pct); axes[1].set_title('Bad-point percentage by metric'); axes[1].set_ylabel('%')\nif not depth_detail.empty:\n    d=depth_detail.groupby(['metric','depth'],as_index=False).bad_point_count.sum()\n    for metric,g in d.groupby('metric'): axes[2].plot(g.depth,g.bad_point_count,marker='o',label=metric.upper())\naxes[2].set_title('Bad points by depth'); axes[2].set_xlabel('Depth'); axes[2].set_ylabel('Count'); axes[2].legend()\nfig.tight_layout(); fig.savefig(QC_ROOT/'population_badpoint_overview.png',dpi=180); display(fig)"]}
]
cells[7]["source"]=["from collections import defaultdict\n\n# Online aggregation: retain only compact counters, never all column rows.\ncategory_counts=defaultdict(int)\ndepth_counts=defaultdict(int)\nfor _,row in files[files.status=='valid'].iterrows():\n    a=np.loadtxt(row.path,delimiter=',',ndmin=2)\n    bad=(~np.isfinite(a))|(a==0)\n    for n in bad.sum(axis=1):\n        category='1' if n==1 else '2' if n==2 else '3_or_more' if n>=3 else '0'\n        category_counts[(row.subject,row.hemi,row.region,row.metric,category)]+=1\n    for depth,n in enumerate(bad.sum(axis=0)):\n        if n: depth_counts[(row.subject,row.hemi,row.region,row.metric,int(depth))]+=int(n)\n    del a,bad\n    gc.collect()\ncolumn_categories=pd.DataFrame([{'subject':k[0],'hemi':k[1],'region':k[2],'metric':k[3],'category':k[4],'column_count':v} for k,v in category_counts.items()])\ndepth_detail=pd.DataFrame([{'subject':k[0],'hemi':k[1],'region':k[2],'metric':k[3],'depth':k[4],'bad_point_count':v} for k,v in depth_counts.items()])\ncolumn_categories.to_csv(QC_ROOT/'bad_points_per_column_summary.csv',index=False)\ndepth_detail.to_csv(QC_ROOT/'depth_bad_point_detail.csv',index=False)\ndisplay(column_categories.head(20)); display(depth_detail.head())"]
